<script lang="ts">
  import { onMount, onDestroy } from 'svelte';
  import { BrowserQRCodeReader } from '@zxing/browser';
  import { api, query } from './api';
  import { readDraft, saveDraft, submitDraft } from './checkout';
  import type { User, Product, Line, Draft, Data } from './types';
  import Receipt from './Receipt.svelte';
  import Photo from './Photo.svelte';
  export let user: User;
  let products: Product[] = [], categories: Data[] = [], cart: Line[] = [], customers: Data[] = [];
  let search = '', category = '', customerSearch = '', selected: Data | null = null, cash = '', tenor = 1, page = 1, more = false;
  let loading = false, busy = false, error = '', invoice: Data | null = null, pending: Draft | null = null, showCustomer = false, scan = false, video: HTMLVideoElement, customerPage = 1, customerMore = false;
  let controls: { stop(): void } | null = null, scanError = '', demo = false;
  const rp = (n: number) => new Intl.NumberFormat('id-ID', { style: 'currency', currency: 'IDR', maximumFractionDigits: 0 }).format(n || 0);
  $: estimate = cart.reduce((sum, line) => sum + Math.round(line.product.harga * line.qty), 0);
  $: isCash = user.role === 'KASIR' && (!selected || selected.tunai || selected.nik === user.default_nik);
  onMount(async () => { pending = readDraft(user); try { categories = await api('/kategori'); if (user.role === 'ANGGOTA') demo = (await api<Data>('/saya/dashboard')).belanja_demo; } catch (e) { error = String((e as Error).message); } await load(); });
  onDestroy(() => controls?.stop());
  async function load(next = false) { loading = true; error = ''; try { const p = next ? page + 1 : 1; const data = await api<Data>('/barang' + query({ q: search.trim(), kategori: category, page: p, size: 30 })); products = next ? [...products, ...data.items] : data.items; page = p; more = data.ada_lagi; } catch (e) { error = (e as Error).message; } finally { loading = false; } }
  function add(p: Product) { const found = cart.find(x => x.product.id === p.id); if (found) found.qty = Math.min(1000, found.qty + 1); else cart.push({ product: p, qty: 1 }); cart = [...cart]; }
  async function findCustomers(next = false) { try { const p = next ? customerPage + 1 : 1; const result = await api<Data>('/pelanggan' + query({ q: customerSearch, page: p, size: 100 })); customers = next ? [...customers, ...result.items] : result.items; customerPage = p; customerMore = result.ada_lagi; } catch (e) { error = (e as Error).message; } }
  async function startScan() { scan = true; scanError = ''; try { await new Promise(r => setTimeout(r, 0)); const reader = new BrowserQRCodeReader(); controls = await reader.decodeFromVideoDevice(undefined, video, async (result) => { if (!result) return; controls?.stop(); scan = false; try { selected = await api('/pelanggan/by-nik/' + encodeURIComponent(result.getText().trim())); showCustomer = false; } catch (e) { error = (e as Error).message; } }); } catch { scanError = 'Kamera tidak tersedia atau izin ditolak. Masukkan NIK melalui pencarian.'; } }
  async function pay(retry = false) { if (busy) return; error = ''; if (!navigator.onLine) { error = 'Tidak ada koneksi. Checkout memerlukan koneksi internet.'; return; }
    if (!retry && (!cart.length || cart.some(l => !Number.isFinite(l.qty) || l.qty <= 0 || l.qty > 1000 || Math.abs(Math.round(l.qty * 100) - l.qty * 100) > 1e-7))) { error = 'Jumlah harus antara 0,01 dan 1000, maksimal dua angka desimal.'; return; }
    if (!retry && isCash && (!cash || Number(cash) < 0 || !Number.isInteger(Number(cash)))) { error = 'Masukkan uang bayar dalam rupiah.'; return; }
    busy = true; try { let draft = retry ? pending : null; if (!draft) { draft = { key: crypto.randomUUID(), userId: user.id, role: user.role, nik: user.role === 'ANGGOTA' ? '' : selected?.nik || user.default_nik, tenor: Number(tenor), ...(isCash ? { uang_bayar: Number(cash) } : {}), baris: cart.map(l => ({ product_id: l.product.id, qty: Number(l.qty) })) }; saveDraft(user, draft); pending = draft; } invoice = await submitDraft(user, draft); pending = null; cart = []; cash = ''; } catch (e) { pending = readDraft(user); error = (e as Error).message; } finally { busy = false; } }
</script>
{#if demo}<div class="notice">MODE DEMO · Belanja anggota hanya simulasi dan tidak tersimpan.</div>{/if}
{#if pending}<div class="notice"><strong>Checkout belum selesai.</strong> Pulihkan transaksi sebelum memulai checkout baru. <button on:click={() => pay(true)} disabled={busy}>Pulihkan checkout</button></div>{/if}
{#if error}<div class="error" role="alert">{error}</div>{/if}
<div class="shop-layout"><section><div class="section-heading"><div><p class="eyebrow">KATALOG PRODUK</p><h2>Pilih barang</h2></div><span class="muted">{products.length} produk</span></div>
<form class="search" on:submit|preventDefault={() => load()}><input aria-label="Cari barang atau barcode" bind:value={search} placeholder="Cari nama atau barcode..."/><button class="secondary">Cari</button></form>
<div class="chips"><button class:active={!category} on:click={() => {category = ''; load();}}>Semua</button>{#each categories as c}<button class:active={category === c.id} on:click={() => {category = c.id; load();}}>{c.nama}</button>{/each}</div>
<div class="product-grid">{#each products as p}<button class="product" on:click={() => add(p)} disabled={!!pending}><span class="product-art">{#if p.foto}<Photo path={'/produk/' + p.id + '/foto'} alt={p.nama} fallback={p.nama.slice(0,2).toUpperCase()}/>{:else}{p.nama.slice(0,2).toUpperCase()}{/if}</span><span class="product-category">{p.kategori || 'PRODUK'}</span><strong>{p.nama}</strong><span class="muted">{p.satuan} {p.stok != null ? `· Stok ${p.stok}` : ''}</span><span class="product-price">{rp(p.harga)} <b>＋</b></span></button>{/each}</div>
{#if loading}<p class="muted">Memuat produk…</p>{:else if !products.length}<p class="empty">Tidak ada produk ditemukan.</p>{/if}{#if more}<button class="secondary wide" on:click={() => load(true)}>Muat lebih banyak</button>{/if}</section>
<aside class="cart panel"><div class="section-heading"><div><p class="eyebrow">TRANSAKSI BARU</p><h2>Keranjang</h2></div><span class="badge">{cart.length}</span></div>
{#if !cart.length}<div class="empty cart-empty">Keranjang masih kosong.<br/>Pilih produk untuk memulai.</div>{/if}
{#each cart as line}<div class="cart-line"><div><strong>{line.product.nama}</strong><small>{rp(line.product.harga)} / {line.product.satuan}</small></div><div class="qty"><input type="number" min="0.01" max="1000" step="0.01" aria-label={'Jumlah ' + line.product.nama} bind:value={line.qty} disabled={!!pending}/><button class="icon" aria-label="Hapus" on:click={() => cart = cart.filter(x => x !== line)} disabled={!!pending}>×</button></div></div>{/each}
{#if user.role === 'KASIR'}<div class="divider"></div><span class="label">Pelanggan</span><button class="select-customer" on:click={() => {showCustomer = true; findCustomers();}} disabled={!!pending}><span>{selected?.nama || 'Pelanggan tunai'}</span><span>Ubah →</span></button>{/if}
<div class="divider"></div><div class="receipt-line"><span>Perkiraan total</span><strong>{rp(estimate)}</strong></div><small class="muted">Total akhir dan potongan dihitung server.</small>
{#if isCash}<label>Uang bayar (Rp)<input type="number" min="0" step="1" bind:value={cash} disabled={!!pending} placeholder="0"/></label>{:else}<label>Tenor (bulan)<input type="number" min="1" max="12" step="1" bind:value={tenor} disabled={!!pending}/></label>{/if}
<button class="primary wide" on:click={() => pay()} disabled={busy || !!pending || !cart.length}>{busy ? 'Memproses…' : isCash ? 'Bayar tunai' : 'Bayar kredit'}</button></aside></div>
{#if showCustomer}<div class="overlay"><section class="modal"><div class="row"><h2>Pilih pelanggan</h2><button class="icon" on:click={() => {showCustomer = false; controls?.stop(); scan = false;}}>×</button></div><button class="secondary wide" on:click={() => {selected = null; showCustomer = false;}}>Pelanggan tunai</button><form class="search" on:submit|preventDefault={() => findCustomers()}><input bind:value={customerSearch} placeholder="Cari nama atau NIK"/><button>Cari</button></form><button class="secondary wide" on:click={startScan}>Scan QR kartu anggota</button>{#if scan}<video bind:this={video} class="scanner" muted playsinline></video>{#if scanError}<p class="error">{scanError}</p>{/if}<button on:click={() => { controls?.stop(); scan = false; }}>Tutup kamera</button>{/if}{#if error}<div class="error">{error}</div>{/if}<div class="scroll-list">{#each customers as c}<button class="list-button" on:click={() => {selected = c; showCustomer = false;}}><strong>{c.nama}</strong><small>{c.nik} · {c.unit_nama}</small></button>{/each}{#if customerMore}<button class="secondary wide" on:click={() => findCustomers(true)}>Muat lebih banyak</button>{/if}</div></section></div>{/if}
{#if invoice}<Receipt {invoice} close={() => invoice = null}/>{/if}
